changeSet.createProcedure:
CREATE OR REPLACE FUNCTION public.wagon_audit_trigger_fn() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO wagon_audit(
            wagon_uuid, number, updated_at, username, operation, old_data, new_data
        ) VALUES (
            NEW.uuid, NEW.number, now(), NEW.username, TG_OP, NULL, row_to_json(NEW)::jsonb
        );
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO wagon_audit(
            wagon_uuid, number, updated_at, username, operation, old_data, new_data
        ) VALUES (
            NEW.uuid, NEW.number, now(), NEW.username, TG_OP, row_to_json(OLD)::jsonb, row_to_json(NEW)::jsonb
        );
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO wagon_audit(
            wagon_uuid, number, updated_at, username, operation, old_data, new_data
        ) VALUES (
            OLD.uuid, OLD.number, now(), OLD.username, TG_OP, current_user, now(), row_to_json(OLD)::jsonb, NULL
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;

changeSet.sql:
DROP TRIGGER IF EXISTS trg_wagon_audit ON wagon;
CREATE TRIGGER trg_wagon_audit
AFTER INSERT OR UPDATE OR DELETE ON wagon
FOR EACH ROW EXECUTE FUNCTION public.wagon_audit_trigger_fn();

changeSet.createProcedure:
CREATE OR REPLACE FUNCTION public.inventory_group_audit_trigger_fn() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO inventory_group_audit(
            inventory_group_uuid, wagon_uuid, username, operation, updated_at, old_data, new_data
        ) VALUES (
            new.uuid, new.wagon_uuid, new.username, TG_OP, now(), null, row_to_json(new)::jsonb
        );
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO inventory_group_audit(
            inventory_group_uuid, wagon_uuid, username, operation, updated_at, old_data, new_data
        ) VALUES (
            new.uuid, new.wagon_uuid, new.username, TG_OP, now(), row_to_json(old)::jsonb, row_to_json(new)::jsonb
        );
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO inventory_group_audit(
            inventory_group_uuid, wagon_uuid, username, operation, updated_at, old_data, new_data
        ) VALUES (
            old.uuid, old.wagon_uuid, old.username, TG_OP, now(), row_to_json(old)::jsonb, null
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$body$;

changeSet.sql:
DROP TRIGGER IF EXISTS trg_inventory_group_audit ON inventory_group;
CREATE TRIGGER trg_inventory_group_audit
AFTER INSERT OR UPDATE OR DELETE ON inventory_group
FOR EACH ROW EXECUTE FUNCTION public.inventory_group_audit_trigger_fn();

