CREATE OR REPLACE FUNCTION public.inventory_item_audit_trigger_fn() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO inventory_item_audit(
            inventory_item_uuid, group_uuid, wagon_uuid, username, operation, updated_at, old_data, new_data
        ) VALUES (
            new.uuid, new.group_uuid, new.wagon_uuid, new.username, tg_op, now(), null, row_to_json(new)::jsonb
        );
        return new;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO inventory_item_audit(
            inventory_item_uuid, group_uuid, wagon_uuid, username, operation, updated_at, old_data, new_data
        ) VALUES (
            new.uuid, new.group_uuid, new.wagon_uuid, new.username, tg_op, now(), row_to_json(old)::jsonb, row_to_json(new)::jsonb
        );
