            inventory_item_uuid, group_uuid, wagon_uuid, username, operation, updated_at, old_data, new_data
        ) VALUES (
            old.uuid, old.group_uuid, old.wagon_uuid, old.username, tg_op, now(), row_to_json(old)::jsonb, null
